function Tarefa({ titulo, feita }) {          // props desmontadas direto
  return (
    <li className={feita ? "feita" : ""}>
      {titulo} {feita && <span>(concluída)</span>}
    </li>
  );
}

function ListaDeTarefas({ tarefas, titulo = "Tarefas" }) {   // valor padrão
  if (tarefas.length === 0) {
    return <p>Nada por aqui ainda.</p>;
  }

  return (
    <section>
      <h2>{titulo} ({tarefas.length})</h2>
      <ul>
        {tarefas.map((t) => (
          <Tarefa key={t.id} titulo={t.titulo} feita={t.feita} />
        ))}
      </ul>
    </section>
  );
}

export default function App() {
  const tarefas = [
    { id: "a1", titulo: "Estudar props", feita: true },
    { id: "a2", titulo: "Entender o key", feita: false },
  ];

  return <ListaDeTarefas tarefas={tarefas} titulo="Da semana" />;
}

