import { useState } from "react";

export default function App() {
  const [tarefas, setTarefas] = useState([]);
  const [texto, setTexto] = useState("");
  const [filtro, setFiltro] = useState("todas");     // estado de tela, não de dado

  function adicionar(evento) {
    evento.preventDefault();
    const titulo = texto.trim();
    if (!titulo) return;
    setTarefas([...tarefas, { id: crypto.randomUUID(), titulo, feita: false }]);
    setTexto("");
  }

  const alternar = (id) =>
    setTarefas(tarefas.map((t) => (t.id === id ? { ...t, feita: !t.feita } : t)));

  const limparFeitas = () => setTarefas(tarefas.filter((t) => !t.feita));

  // calculado na hora de desenhar: o array continua inteiro
  const visiveis =
    filtro === "pendentes" ? tarefas.filter((t) => !t.feita)
    : filtro === "feitas" ? tarefas.filter((t) => t.feita)
    : tarefas;

  return (
    <main>
      <h1>Minhas tarefas</h1>

      <form onSubmit={adicionar}>
        <label htmlFor="texto">Nova tarefa</label>
        <input id="texto" value={texto} onChange={(e) => setTexto(e.target.value)} />
        <button>Adicionar</button>
      </form>

      <div role="group" aria-label="Filtro">
        {["todas", "pendentes", "feitas"].map((f) => (
          <button key={f} type="button" aria-pressed={filtro === f} onClick={() => setFiltro(f)}>
            {f}
          </button>
        ))}
      </div>

      <ul>
        {visiveis.map((t) => (
          <li key={t.id} className={t.feita ? "feita" : ""}>
            <input type="checkbox" checked={t.feita} onChange={() => alternar(t.id)} />
            <span>{t.titulo}</span>
          </li>
        ))}
      </ul>

      {visiveis.length === 0 && <p>Nenhuma tarefa neste filtro.</p>}

      <button type="button" onClick={limparFeitas}>Limpar concluídas</button>
    </main>
  );
}

// o aria-pressed conta pro leitor de tela qual filtro está ativo.
// e repare: visiveis é calculado, não guardado. Um estado a menos
// é um jeito a menos de a tela discordar do dado.

