import { useEffect, useState } from "react";

export default function App() {
  const [tarefas, setTarefas] = useState([]);
  const [carregando, setCarregando] = useState(true);
  const [erro, setErro] = useState(null);

  useEffect(() => {
    let vivo = true;                       // evita atualizar tela que já saiu

    async function carregar() {
      try {
        const resposta = await fetch("/tarefas.json");
        if (!resposta.ok) throw new Error(`status ${resposta.status}`);

        const dados = await resposta.json();
        if (vivo) setTarefas(dados);
      } catch (e) {
        if (vivo) setErro("Não consegui carregar a lista.");
        console.error(e);
      } finally {
        if (vivo) setCarregando(false);
      }
    }

    carregar();
    return () => { vivo = false; };        // limpeza, quando o componente sai
  }, []);                                  // [] = roda uma vez, ao montar

  if (carregando) return <p>Carregando...</p>;
  if (erro) return <p role="alert">{erro}</p>;

  return (
    <main>
      <h1>Tarefas ({tarefas.length})</h1>
      <ul>
        {tarefas.map((t) => (
          <li key={t.id}>{t.titulo}</li>
        ))}
      </ul>
    </main>
  );
}

