import { useEffect, useState } from "react";

export default function App() {
  const [itens, setItens] = useState([]);
  const [carregando, setCarregando] = useState(true);
  const [erro, setErro] = useState(null);
  const [busca, setBusca] = useState("");

  useEffect(() => {
    let vivo = true;

    (async () => {
      try {
        const r = await fetch("/tarefas.json");
        if (!r.ok) throw new Error(`status ${r.status}`);
        const dados = await r.json();
        if (vivo) setItens(dados);
      } catch (e) {
        if (vivo) setErro("Não consegui carregar a lista. Tente de novo em instantes.");
        console.error(e);
      } finally {
        if (vivo) setCarregando(false);
      }
    })();

    return () => { vivo = false; };
  }, []);

  // filtro calculado: os dados originais continuam intactos
  const termo = busca.trim().toLowerCase();
  const visiveis = termo
    ? itens.filter((i) => i.titulo.toLowerCase().includes(termo))
    : itens;

  if (carregando) return <p>Carregando...</p>;
  if (erro) return <p role="alert">{erro}</p>;

  return (
    <main>
      <h1>Tarefas</h1>

      <label htmlFor="busca">Buscar</label>
      <input id="busca" value={busca} onChange={(e) => setBusca(e.target.value)}
             placeholder="filtrar pelo título" />

      <p>{visiveis.length} de {itens.length}</p>

      <ul>
        {visiveis.map((i) => (
          <li key={i.id}>{i.titulo}</li>
        ))}
      </ul>

      {visiveis.length === 0 && <p>Nada encontrado para "{busca}".</p>}
    </main>
  );
}

